namespace http.purl.oclc.org.NET.ssnx.cf.cf_property.hash

open DoxAletheia.Rdf_Vocabulary

module cfp =
    let _namespace_name = "http://purl.oclc.org/NET/ssnx/cf/cf-property#"

    /// <summary>
    /// "Age of stratospheric air" means an estimate of the time since a parcel of stratospheric air was last in contact with the troposphere.
    /// <see href="http://purl.oclc.org/NET/ssnx/cf/cf-property#age_of_stratospheric_air"></see></summary>
    let age_of_stratospheric_air =
        Namespaced_IRI.parse _namespace_name "age_of_stratospheric_air" |> NamespacedName

    /// <summary>
    ///   <see href="http://purl.oclc.org/NET/ssnx/cf/cf-property#air_density"></see>
    /// </summary>
    let air_density =
        Namespaced_IRI.parse _namespace_name "air_density" |> NamespacedName

    /// <summary>
    /// Potential temperature is the temperature a parcel of air or sea water would have if moved adiabatically to sea level pressure.
    /// <see href="http://purl.oclc.org/NET/ssnx/cf/cf-property#air_potential_temperature"></see></summary>
    let air_potential_temperature =
        Namespaced_IRI.parse _namespace_name "air_potential_temperature" |> NamespacedName

    /// <summary>
    ///   <see href="http://purl.oclc.org/NET/ssnx/cf/cf-property#air_pressure"></see>
    /// </summary>
