    /// <see href="http://purl.oclc.org/NET/ssnx/cf/cf-property#atmosphere_absorption_optical_thickness_due_to_sulfate_ambient_aerosol"></see></summary>
    let atmosphere_absorption_optical_thickness_due_to_sulfate_ambient_aerosol =
        Namespaced_IRI.parse _namespace_name "atmosphere_absorption_optical_thickness_due_to_sulfate_ambient_aerosol" |> NamespacedName

